 "genere": "prevedi",
 "titolo": "Previsioni sulle animazioni",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> bool:
	var animated_sprite := AnimatedSprite2D.new()
	var direction: float = -1.0
	if direction > 0.0:
		animated_sprite.flip_h = false
	elif direction < 0.0:
		animated_sprite.flip_h = true
	return animated_sprite.flip_h
",
   "domanda": "Quanto vale `animated_sprite.flip_h` alla fine?",
   "spiegazione": "Dato che `direction` è `-1.0`, la condizione `direction < 0.0` è vera, quindi `flip_h` viene impostato su `true` per girare lo sprite a sinistra."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var on_floor: bool = true
	var velocity_x: float = 5.0
	var current_anim: String = ""

	if on_floor:
		if abs(velocity_x) > 10.0:
			current_anim = "run"
		else:
			current_anim = "idle"
	else:
		current_anim = "fall"
	return current_anim
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "Il personaggio è a terra (`on_floor` è vero), ma `abs(velocity_x)` vale 5.0, che non è maggiore di 10.0. Viene quindi scelta l'animazione "idle"."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var on_floor: bool = false
	var velocity_y: float = -150.0
	var current_anim: String = ""

	if on_floor:
		current_anim = "idle"
	else:
		if velocity_y < 0.0:
			current_anim = "jump"
		else:
			current_anim = "fall"
	return current_anim
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "Il personaggio non è a terra (`on_floor` è falso). La velocità verticale `velocity_y` è negativa (-150.0), segno che sta salendo: viene attivata l'animazione "jump"."
  },
  {
   "codice": "extends RefCounted


func run() -> bool:
	var animated_sprite := AnimatedSprite2D.new()
	animated_sprite.flip_h = true
	var direction: float = 0.0

	if direction > 0.0:
		animated_sprite.flip_h = false
	elif direction < 0.0:
		animated_sprite.flip_h = true

	return animated_sprite.flip_h
",
